/**
 * Parse a raw task payload into a task. Per the README, the parsed `priority`
 * is a non-negative integer (radix 10); invalid input throws loudly.
 */
export function parseTask(payload) {
  if (payload === null || typeof payload !== 'object') {
    throw new TypeError('payload must be an object')
  }
  const raw = payload.priority
  if (typeof raw !== 'string') {
    throw new TypeError('priority must be a string')
  }
  const trimmed = raw.trim()
  return { id: payload.id, priority: trimmed }
}

/**
 * Compare two parsed tasks: lower priority number first. Per the README,
 * `compare` receives already-parsed tasks (priority is an integer).
 */
export function compare(taskA, taskB) {
  if (taskA.priority < taskB.priority) return -1
  if (taskA.priority > taskB.priority) return 1
  return 0
}

import { compare } from './compare.js'

/**
 * Priority queue: lower priority first, ties broken by FIFO insertion order.
 * `drain()` does not mutate the queue.
 */
export function createQueue() {
  let nextSeq = 0
  const items = []

  return {
    enqueue(task) {
      items.push({ task, seq: nextSeq++ })
    },
    drain() {
      return items
        .slice()
        .sort((a, b) => compare(a.task, b.task) || a.seq - b.seq)
        .map((item) => item.task)
    },
    size: () => items.length,
  }
}

import { parseTask } from './parse.js'
import { createQueue } from './queue.js'

/** Build a queue from raw payloads and return the drained task ids. */
export function runOrder(payloads) {
  const queue = createQueue()
  for (const payload of payloads) {
    queue.enqueue(parseTask(payload))
  }
  return queue.drain().map((task) => task.id)
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { parseTask } from '../src/parse.js'

test('parse: priority is a non-negative integer in the parsed task', () => {
  const task = parseTask({ id: 'a', priority: ' 10 ' })
  assert.deepEqual(task, { id: 'a', priority: 10 })
  assert.equal(typeof task.priority, 'number')
})

test('parse: throws on non-numeric priority', () => {
  assert.throws(() => parseTask({ id: 'x', priority: 'soon' }), RangeError)
})

test('parse: throws on negative priority', () => {
  assert.throws(() => parseTask({ id: 'x', priority: '-3' }), RangeError)
})

test('parse: preserves the task id', () => {
  assert.equal(parseTask({ id: 'keep-me', priority: '7' }).id, 'keep-me')
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { runOrder } from '../src/scheduler.js'
import { createQueue } from '../src/queue.js'
import { parseTask } from '../src/parse.js'

test('scheduler: lower priority number runs first across digit widths', () => {
  // With integer priorities: 1, 2, 10. A lexicographic ordering of raw strings
  // would yield 1, 10, 2.
  const order = runOrder([
    { id: 'a', priority: '2' },
    { id: 'b', priority: '10' },
    { id: 'c', priority: '1' },
  ])
  assert.deepEqual(order, ['c', 'a', 'b'])
})

test('scheduler: ties keep FIFO insertion order', () => {
  const order = runOrder([
    { id: 'a', priority: '5' },
    { id: 'b', priority: '5' },
    { id: 'c', priority: '5' },
  ])
  assert.deepEqual(order, ['a', 'b', 'c'])
})

test('scheduler: mixed priorities with ties', () => {
  const order = runOrder([
    { id: 'a', priority: '3' },
    { id: 'b', priority: '1' },
    { id: 'c', priority: '3' },
    { id: 'd', priority: '2' },
  ])
  assert.deepEqual(order, ['b', 'd', 'a', 'c'])
})

test('queue: drain does not mutate the queue', () => {
  const queue = createQueue()
  queue.enqueue(parseTask({ id: 'a', priority: '2' }))
  queue.enqueue(parseTask({ id: 'b', priority: '1' }))
  const first = queue.drain().map((task) => task.id)
  const second = queue.drain().map((task) => task.id)
  assert.deepEqual(first, ['b', 'a'])
  assert.deepEqual(second, ['b', 'a'])
  assert.equal(queue.size(), 2)
})

